To solve this problem, you need to implement a **Global Tooltip Provider**.

Since Next.js components are isolated, you cannot rely on `useState` inside a single component to track the state of tooltips opened elsewhere. Instead, you must lift the state up to a Context Provider that wraps your entire application (or the specific layout where you want the tooltip to work).

Here is the complete solution using **React Context** and **Tailwind CSS** (standard in Next.js).

### 1. Create the Context and Provider

First, create a file to hold the state and the logic for opening/closing tooltips globally.

`context/TooltipContext.tsx`

```tsx
'use client';

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Define the shape of our context
interface TooltipContextType {
  open: boolean;
  content: string;
  position: 'top' | 'bottom' | 'left' | 'right';
  openTooltip: (content: string, position?: 'top' | 'bottom' | 'left' | 'right') => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider = ({ children }: { children: ReactNode }) => {
  const [open, setOpen] = useState(false);
  const [content, setContent] = useState('');
  const [position, setPosition] = useState<'top' | 'bottom' | 'left' | 'right'>('top');

  const openTooltip = useCallback((newContent: string, newPosition?: 'top' | 'bottom' | 'left' | 'right') => {
    setContent(newContent);
    setPosition(newPosition || 'top');
    setOpen(true);
  }, []);

  const closeTooltip = useCallback(() => {
    setOpen(false);
  }, []);

  return (
    <TooltipContext.Provider value={{ open, content, position, openTooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
```

