To make Bootstrap tables sortable alphanumerically by clicking the headers without using jQuery or other plugins, you can use the HTML5 Drag and Drop API. Here’s a step-by-step guide:

1. **HTML Structure**: Ensure your table has a structure that supports sorting. Each header cell (`<th>`) should have a unique identifier or class to distinguish it from other headers.

2. **CSS Styling**: Add some CSS to style the headers and indicate which header is currently being sorted. For example, you can add a class like `.sorted` to highlight the active sort column.

3. **JavaScript Implementation**:
   - Use the `dragstart` event to capture the header that is being dragged.
   - Use the `dragover` event to allow dropping on other headers.
   - Use the `drop` event to handle the sorting logic.
   - Implement the sorting logic to reorder the rows based on the clicked header.

Here is a basic example:

```html
<table class="table">
  <thead>
    <tr>
      <th draggable="true" id="header1">Name</th>
      <th draggable="true" id="header2">Age</th>
    </tr>
  </thead>
  <tbody>
    <tr><td>Alice</td><td>25</td></tr>
    <tr><td>Bob</td><td>30</td></tr>
    <tr><td>Charlie</td><td>35</td></tr>
  </tbody>
</table>

<script>
  const headers = document.querySelectorAll('th[draggable="true"]');
  const rows = document.querySelectorAll('tbody tr');

  headers.forEach(header => {
    header.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/plain', header.id);
    });
  });

  headers.forEach(header => {
    header.addEventListener('dragover', (e) => {
      e.preventDefault();
    });
  });

  headers.forEach(header => {
    header.addEventListener('drop', (e) => {
      e.preventDefault();
      const draggedHeaderId = e.dataTransfer.getData('text/plain');
      const sortedHeaderId = header.id;

      if (draggedHeaderId !== sortedHeaderId) {
        sortTable(draggedHeaderId, sortedHeaderId);
      }
    });
  });

  function sortTable(draggedHeaderId, sortedHeaderId) {
    const draggedHeader = document.getElementById(draggedHeaderId);
    const sortedHeader = document.getElementById(sortedHeaderId);

    // Determine the sort direction
    const isAscending = draggedHeader.classList.contains('asc');
    const direction = isAscending ? 'desc' : 'asc';

    // Sort the rows
    rows.sort((a, b) => {
      const cellA = a.querySelector(`td:nth-child(${Array.from(headers).indexOf(draggedHeader) + 1})`).textContent;
      const cellB = b.querySelector(`td:nth-child(${Array.from(headers).indexOf(draggedHeader) + 1})`).textContent;

      if (cellA < cellB) return direction === 'asc' ? -1 : 1;
      if (cellA > cellB) return direction === 'asc' ? 1 : -1;
      return 0;
    });

    // Update the sort direction
    draggedHeader.classList.toggle('asc');
    draggedHeader.classList.toggle('desc');
  }
</script>
```

This code sets up a basic sortable table using the HTML5 Drag and Drop API. You can customize the sorting logic and styling as needed.

