#### 2. The Backend Code (`server.js`)

This endpoint handles the search logic. It performs a "LIKE" query with a wildcard (`%`) to match partial strings.

```javascript
const express = require('express');
const { Pool } = require('pg');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

// Database Connection
const pool = new Pool({
  user: 'postgres',
  host: 'localhost',
  database: 'hotel_db',
  password: 'password',
  port: 5432,
});

// 1. Backend Filtering Function
async function searchHotels(query) {
  if (!query || query.length < 2) return []; // Minimum 2 chars to search

  const client = await pool.connect();
  try {
    // We use ILIKE for case-insensitive search
    const result = await client.query(
      `SELECT id, name, city, country, rating 
       FROM hotels 
       WHERE name ILIKE $1 
       ORDER BY name ASC 
       LIMIT 10`,
      [`%${query}%`]
    );
    return result.rows;
  } finally {
    client.release();
  }
}

// 2. API Endpoint
app.get('/api/hotels', async (req, res) => {
  const { q } = req.query; // 'q' stands for query

  if (!q) {
    return res.status(400).json({ error: 'Query parameter "q" is required' });
  }

  try {
    const hotels = await searchHotels(q);
    res.json({
      status: 'success',
      data: hotels
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

const PORT = 3000;
app.listen(PORT, () => console.log(`Server running on http://localhost:${PORT}`));
