// 2. Define the filename
const filename = 'my-screenshot.png';

// 3. Construct the full path
// This ensures the file goes exactly where you want it
const filePath = path.join(baseDir, filename);

// 4. Ensure the directory exists
// If 'journey-snaps/screenshots' doesn't exist yet, this creates it
if (!fs.existsSync(baseDir)) {
  fs.mkdirSync(baseDir, { recursive: true });
}

// 5. Save the file
// 'data' is the binary data of your image (Buffer)
fs.writeFile(filePath, data, (err) => {
  if (err) {
    console.error('Error saving file:', err);
  } else {
    console.log(`File saved successfully to: ${filePath}`);
  }
});
```

